      "olcut": "Arada bir sayı bulmak için yol kurma: iki sayının ortalamasını alma (örn. (1/4 + 1/3) ÷ 2) ya da paydaları genişletip arada kesir arama. Doğru sonuca götüren tüm yollar kabul edilir.",
