    "secenekler": null,
    "cevap": "1. 2x − 8 = 0 ⇒ x = 4. 2. x < 4 iken g(x) = −2x + 8; x ≥ 4 iken g(x) = 2x − 8. 3. 1 < 4: g(1) = −2 + 8 = 6. 4. 7 ≥ 4: g(7) = 14 − 8 = 6. 5. 1 ≠ 7 olduğu hâlde g(1) = g(7) = 6; g bire bir değildir.",
